**Keygen 通用框架（Windows x64，C，可直接编译）**

```c
#include <stdio.h>
#include <string.h>
#include <stdint.h>

/* ---------- 1. 校验函数：原样复刻目标程序的算法 ---------- */
/* 从反编译里抄过来，务必一字不差（含常量、位宽、溢出行为） */
uint32_t target_checksum(const char *name, const uint8_t *salt, size_t saltlen) {
    uint32_t h = 0x1505u;                 /* 占位：替换为真实初始值 */
    for (const char *p = name; *p; ++p) {
        h = h * 33u + (uint8_t)*p;        /* 占位：真实混合方式 */
    }
    for (size_t i = 0; i < saltlen; ++i) {
        h ^= salt[i];
        h = (h << 5) | (h >> 27);         /* 占位：真实旋转/移位 */
    }
    return h;
}

/* ---------- 2. 序列号格式化 ---------- */
/* 常见形态：分组成 %04X-%04X-...，字符集被限制到 [0-9A-Z] 去掉了易混字符 */
static void format_serial(uint32_t *parts, int n, char *out) {
    static const char CS[] = "0123456789ABCDEFGHJKLMNPQRSTUVWXYZ"; /* 占位 charset */
    char *w = out;
    for (int i = 0; i < n; ++i) {
        uint32_t v = parts[i];
        for (int k = 4; k >= 0; --k) {            /* 每组 5 字符 */
            *w++ = CS[(v >> (k * 5)) & 0x1F];
        }
        if (i != n - 1) *w++ = '-';
    }
    *w = 0;
}

/* ---------- 3. 反向求解：由 h 反推可打印序列号 ---------- */
/* 若算法可逆 -> 直接逆运算；不可逆 -> 固定前 N-1 组随机枚举最后一组 */
int derive(const char *name, const uint8_t *salt, size_t saltlen,
           char *serial, size_t serlen) {
    const uint32_t want = 0xA5A5A5A5u;   /* 占位：目标期望的校验值 */

    /* 路线 A：可逆（纯 XOR / 加减 / 位旋转）——直接代数逆推 */
    /* 路线 B：不可逆（乘法混合 / 查表）——枚举填充位 */
    uint32_t p[4] = {0};
    /* 占位：这里放真实逆推。示例按 4 组 5 位枚举最后一组 */
    for (uint32_t x = 0; x < (1u << 20); ++x) {
        p[3] = x;
        char tmp[64];
        format_serial(p, 4, tmp);
        if (target_checksum(tmp, salt, saltlen) == want) {
            snprintf(serial, serlen, "%s", tmp);
            return 1;
        }
    }
    return 0;
}

int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s <username>\n", argv[0]); return 1; }
    const uint8_t salt[] = {0x00};       /* 占位：真实 salt / 魔数 */
    char serial[128];
    if (!derive(argv[1], salt, sizeof(salt), serial, sizeof(serial))) {
        fprintf(stderr, "no match\n");
        return 2;
    }
    printf("%s -> %s\n", argv[1], serial);
    return 0;
}
```

