## 脚本（先给能直接跑的，占位符替换即可）

### 1. Frida JS —— hook JNI 校验函数入口/出口 + 参数/返回值/调用栈

`hook_jni_check.js`

```javascript
// 目标 SO：lib[so名].so   JNI 函数：[Java_包名_类名_方法名] 或 导出符号
// 占位符替换：[SO_NAME] [JNI_SYMBOL] [MODULE_BASE_OFFSET]

const SO_NAME    = "lib[so名].so";
const JNI_SYMBOL = "Java_com_[包名]_[类名]_[方法名]"; // 或 "Java_...__Ljava_lang_String_2"
const CHECK_OFF  = 0x[函数偏移];  // 若走导出符号则不需要；若是内部校验函数（非导出）用这个

function ts() { return new Date().toISOString(); }
function hexdumpArgs(args, n) {
  let s = [];
  for (let i = 0; i < n; i++) {
    try { s.push(`a[${i}]=${args[i]}`); } catch (e) {}
  }
  return s.join(" ");
}

function logBacktrace(ctx) {
  try {
    const bt = Thread.backtrace(ctx, Backtracer.FUZZY)
      .map(ptr => {
        const sym = DebugSymbol.fromAddress(ptr);
        const m = Process.findModuleByAddress(ptr);
        return `${ptr} ${m ? m.name + "+0x" + ptr.sub(m.base).toString(16) : ""} ${sym.name || ""}`;
      });
    console.log("  BT:\n    " + bt.join("\n    "));
  } catch (e) { console.log("  BT failed: " + e); }
}

function hookByExport() {
  const addr = Module.findExportByName(SO_NAME, JNI_SYMBOL);
  if (!addr) { console.log(`[!] export not found: ${JNI_SYMBOL} in ${SO_NAME}`); return false; }
  console.log(`[+] hook export ${JNI_SYMBOL} @ ${addr}`);
  Interceptor.attach(addr, {
    onEnter(args) {
      this.t = ts();
      console.log(`\n[${this.t}] ENTER ${JNI_SYMBOL}`);
      console.log("  " + hexdumpArgs(args, 6));
      // env=args[0], thiz/class=args[1], 之后是 JNI 方法实参
      logBacktrace(this.context);
    },
    onLeave(retval) {
      console.log(`[${ts()}] LEAVE ${JNI_SYMBOL} retval=${retval} (int=${retval.toInt32()})`);
    }
  });
  return true;
}

function hookByOffset() {
  const base = Module.findBaseAddress(SO_NAME);
  if (!base) { console.log(`[!] module not loaded: ${SO_NAME}`); return; }
  const addr = base.add(CHECK_OFF);
  console.log(`[+] hook offset ${SO_NAME}+0x${CHECK_OFF.toString(16)} -> ${addr}`);
  Interceptor.attach(addr, {
    onEnter(args) {
      console.log(`\n[${ts()}] ENTER ${SO_NAME}+0x${CHECK_OFF.toString(16)}`);
      console.log("  " + hexdumpArgs(args, 6));
      logBacktrace(this.context);
    },
    onLeave(retval) {
      console.log(`[${ts()}] LEAVE retval=${retval} (int=${retval.toInt32()})`);
    }
  });
}

// 等 SO 加载完再挂
function waitAndHook() {
  let m = Process.findModuleByName(SO_NAME);
  if (m) { run(); return; }
  const iv = setInterval(() => {
    m = Process.findModuleByName(SO_NAME);
    if (m) { clearInterval(iv); run(); }
  }, 50);
  function run() {
    console.log(`[+] ${SO_NAME} base=${Process.findModuleByName(SO_NAME).base}`);
    if (!hookByExport()) hookByOffset();
  }
}
waitAndHook();
```

