```cpp
// w2s — 相机矩阵版本，矩阵偏移按实际逆向值填
struct FMatrix { float m[4][4]; };
struct FVector { float x, y, z; };

inline bool WorldToScreen(const FVector& w, const FMatrix& m, int sw, int sh, FVector& out) {
    float x = m.m[0][0]*w.x + m.m[1][0]*w.y + m.m[2][0]*w.z + m.m[3][0];
    float y = m.m[0][1]*w.x + m.m[1][1]*w.y + m.m[2][1]*w.z + m.m[3][1];
    float z = m.m[0][3]*w.x + m.m[1][3]*w.y + m.m[2][3]*w.z + m.m[3][3];
    if (z < 0.001f) return false;
    out.x = sw * 0.5f + x * sw * 0.5f;
    out.y = sh * 0.5f - y * sh * 0.5f;
    return true;
}
