// aim_base.cpp — Windows x64, MSVC /MT, 需以管理员运行
#include <windows.h>
#include <TlHelp32.h>
#include <stdio.h>
#include <math.h>

static DWORD  g_Pid   = 0;
static HANDLE g_Proc  = nullptr;
static uintptr_t g_Base = 0;
static DWORD  g_PidSize = 0;

DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe))
        if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(snap); return pe.th32ProcessID; }
    CloseHandle(snap); return 0;
}

uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me))
        if (!_wcsicmp(me.szModule, mod)) { CloseHandle(snap); return (uintptr_t)me.modBaseAddr; }
    CloseHandle(snap); return 0;
}

template <class T> bool RPM(uintptr_t addr, T& out) {
    SIZE_T n = 0;
    return ReadProcessMemory(g_Proc, (LPCVOID)addr, &out, sizeof(T), &n) && n == sizeof(T);
}
template <class T> bool WPM(uintptr_t addr, const T& in) {
    SIZE_T n = 0;
    return WriteProcessMemory(g_Proc, (LPVOID)addr, &in, sizeof(T), &n) && n == sizeof(T);
}

// 多级指针链：offsets 从高到低给出，例：{0x1D8, 0x80, 0x2A0}
uintptr_t ResolveChain(uintptr_t base, const uint32_t* offs, int n) {
    uintptr_t p = base;
    for (int i = 0; i < n; ++i) {
        if (!RPM<uintptr_t>(p + offs[i], p)) return 0;
        if (!p || p < 0x10000) return 0;
    }
    return p;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = (argc > 1) ? argv[1] : L"[进程名].exe";
    const wchar_t* mod  = (argc > 2) ? argv[2] : L"[模块名].exe";

    g_Pid = FindPid(proc);
    if (!g_Pid) { wprintf(L"进程未找到: %s\n", proc); return 1; }

    g_Proc = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION
                         | PROCESS_QUERY_INFORMATION, FALSE, g_Pid);
    if (!g_Proc) { wprintf(L"OpenProcess 失败: %lu\n", GetLastError()); return 1; }

    g_Base = GetModuleBase(g_Pid, mod);
    wprintf(L"PID=%lu  Base=%p\n", g_Pid, (void*)g_Base);
    return 0;
}
