#include <ntifs.h>
#include <ntddk.h>

#define DEV_NAME   L"\\Device\\rwdrv"
#define SYM_NAME   L"\\DosDevices\\rwdrv"

typedef struct _RW_REQ {
    HANDLE ProcessId;      // 目标 pid
    PVOID  Address;        // 目标地址（远端）
    PVOID  Buffer;         // 本进程缓冲区
    SIZE_T Size;
    ULONG  IsWrite;        // 0=读 1=写
} RW_REQ, *PRW_REQ;

static NTSTATUS DoCopy(PRW_REQ req) {
    PEPROCESS src = NULL, dst = NULL;
    NTSTATUS st;
    if (!req || !req->Address || !req->Buffer || req->Size == 0) return STATUS_INVALID_PARAMETER;

    st = PsLookupProcessByProcessId(req->ProcessId, &src);
    if (!NT_SUCCESS(st)) return st;

    dst = PsGetCurrentProcess();
    KAPC_STATE apc;
    if (req->IsWrite) {
        KeStackAttachProcess(src, &apc);   // 写：挂到目标进程上下文
        __try {
            RtlCopyMemory(req->Address, req->Buffer, req->Size);
        } __except (EXCEPTION_EXECUTE_HANDLER) {
            st = GetExceptionCode();
        }
        KeUnstackDetachProcess(&apc);
        ObDereferenceObject(src);
        return st;
    } else {
        st = MmCopyVirtualMemory(src, req->Address, dst, req->Buffer, req->Size, KernelMode, NULL);
        ObDereferenceObject(src);
        return st;
    }
}

static NTSTATUS DispatchCreate(PDEVICE_OBJECT dev, PIRP irp) {
    irp->IoStatus.Status = STATUS_SUCCESS;
    irp->IoStatus.Information = 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

static NTSTATUS DispatchClose(PDEVICE_OBJECT dev, PIRP irp) {
    irp->IoStatus.Status = STATUS_SUCCESS;
    irp->IoStatus.Information = 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

// IOCTL 0x800 读写统一入口：METHOD_BUFFERED，输入 RW_REQ，输出 Status
#define IOCTL_RW CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)

static NTSTATUS DispatchIoctl(PDEVICE_OBJECT dev, PIRP irp) {
    PIO_STACK_LOCATION irpSp = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;
    ULONG info = 0;

    if (irpSp->Parameters.DeviceIoControl.IoControlCode == IOCTL_RW &&
        irpSp->Parameters.DeviceIoControl.InputBufferLength >= sizeof(RW_REQ)) {
        PRW_REQ req = (PRW_REQ)irp->AssociatedIrp.SystemBuffer;
        st = DoCopy(req);
        irp->IoStatus.Status = st;
        info = sizeof(NTSTATUS);
    }
    irp->IoStatus.Information = info;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

