```c
// hide_proc.c — Windows x64 最小验证骨架
// 目标：验证进程名伪装 + 句柄保护两层是否生效
#include <windows.h>
#include <stdio.h>

// 1) 进程名伪装：改 PEB->ProcessParameters->ImagePathName / CommandLine
static void PatchPebImageName(const wchar_t* fake) {
    HANDLE hProc = GetCurrentProcess();
    PROCESS_BASIC_INFORMATION pbi = {0};
    ULONG len = 0;
    NtQueryInformationProcess(hProc, 0, &pbi, sizeof(pbi), &len);

    // PEB + 0x20 -> ProcessParameters (x64)
    PBYTE peb = (PBYTE)pbi.PebBaseAddress;
    PBYTE* ppPtr = (PBYTE*)(peb + 0x20);
    PBYTE pp = *ppPtr;
    if (!pp) return;

    // UNICODE_STRING ImagePathName @ 0x60, CommandLine @ 0x70 (x64 Win10/11)
    PUNICODE_STRING img = (PUNICODE_STRING)(pp + 0x60);
    if (img->Buffer) {
        DWORD old = 0;
        SIZE_T sz = (wcslen(fake) + 1) * sizeof(wchar_t);
        VirtualProtect(img->Buffer, sz, PAGE_READWRITE, &old);
        memcpy(img->Buffer, fake, sz);
        img->Length = (USHORT)(sz - sizeof(wchar_t));
        img->MaximumLength = (USHORT)sz;
        VirtualProtect(img->Buffer, sz, old, &old);
    }
}

int main(void) {
    PatchPebImageName(L"C:\\Windows\\System32\\svchost.exe");
    printf("[*] PEB ImagePathName patched, pid=%lu\n", GetCurrentProcessId());
    // 2) 句柄保护 → 需内核驱动 ObRegisterCallbacks 实现，见下一步
    getchar();
    return 0;
}
```

