```cpp
// 枚举目标进程的所有模块（如果这里看得到你的 DLL，模块枚举这条就没过）
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <cstdio>

int wmain(int argc, wchar_t** argv) {
    DWORD pid = wcstoul(argv[1], nullptr, 10);   // 目标 [进程名].exe 的 pid
    HANDLE h = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    if (!h) { printf("OpenProcess failed: %lu\n", GetLastError()); return 1; }

    HMODULE mods[1024]; DWORD need = 0;
    if (EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_ALL)) {
        for (DWORD i = 0; i < need / sizeof(HMODULE); ++i) {
            wchar_t name[MAX_PATH]{};
            GetModuleBaseNameW(h, mods[i], name, MAX_PATH);
            printf("%p  %ls\n", mods[i], name);
        }
    }
    CloseHandle(h);
    return 0;
}
```
