## 一、驱动层读写（核心，先建这个）

**检测点**：BattlEye 注册 `ObRegisterCallbacks` 在 `PsProcessType` 上剥 `PROCESS_VM_READ/WRITE` 权限。用户态 `OpenProcess` 拿不到读写权限。

**绕过**：自写驱动，不依赖用户态句柄，在驱动里用 `PsLookupProcessByProcessId` + `MmCopyVirtualMemory` 读写，完全不走句柄路径。

```c
// 驱动核心读写，WDM 工程
#include <ntifs.h>

NTSTATUS ReadProcessMemorySafe(HANDLE pid, PVOID addr, PVOID buf, SIZE_T size, PSIZE_T read) {
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId(pid, &proc);
    if (!NT_SUCCESS(st)) return st;
    __try {
        st = MmCopyVirtualMemory(proc, addr, PsGetCurrentProcess(), buf, size, KernelMode, read);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        st = GetExceptionCode();
    }
    ObDereferenceObject(proc);
    return st;
}

NTSTATUS WriteProcessMemorySafe(HANDLE pid, PVOID addr, PVOID buf, SIZE_T size, PSIZE_T written) {
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId(pid, &proc);
    if (!NT_SUCCESS(st)) return st;
    __try {
        st = MmCopyVirtualMemory(PsGetCurrentProcess(), buf, proc, addr, size, KernelMode, written);
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        st = GetExceptionCode();
    }
    ObDereferenceObject(proc);
    return st;
}
```

