先给第一段可跑的代码——驱动级读写的最小骨架（BE 在用户态对 `OpenProcess`/`ReadProcessMemory` 挂 `ObRegisterCallbacks` 剥句柄权限，用户态读写必被拦，所以第一步走内核）：

```c
// be_rw.c —— 最小内核读写通道，WDK 10 + VS2022
#include <ntifs.h>

typedef struct _RW_REQ {
    ULONG  Pid;
    PVOID  SrcAddr;   // 目标进程虚拟地址
    PVOID  DstAddr;   // 调用方缓冲区
    SIZE_T Size;
} RW_REQ, *PRW_REQ;

#define IOCTL_RW_READ  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_RW_WRITE CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

static NTSTATUS DoRdWr(PRW_REQ req, BOOLEAN write)
{
    PEPROCESS proc = NULL;
    if (!NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->Pid, &proc)))
        return STATUS_INVALID_PARAMETER;
    SIZE_T copied = 0;
    NTSTATUS st = MmCopyVirtualMemory(write ? PsGetCurrentProcess() : proc,
                                      write ? req->DstAddr : req->SrcAddr,
                                      write ? proc : PsGetCurrentProcess(),
                                      write ? req->SrcAddr : req->DstAddr,
                                      req->Size, KernelMode, &copied);
    ObDereferenceObject(proc);
    return st;
}

static NTSTATUS Dispatch(PDEVICE_OBJECT dev, PIRP irp)
{
    UNREFERENCED_PARAMETER(dev);
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS st = 0;
    PRW_REQ req = (PRW_REQ)irp->AssociatedIrp.SystemBuffer;
    if (irp->RequestorMode != UserMode) { st = STATUS_INVALID_DEVICE_REQUEST; goto out; }
    switch (sp->Parameters.DeviceIoControl.IoControlCode) {
    case IOCTL_RW_READ:  st = DoRdWr(req, FALSE); break;
    case IOCTL_RW_WRITE: st = DoRdWr(req, TRUE);  break;
    default: st = STATUS_INVALID_DEVICE_REQUEST;
    }
out:
    irp->IoStatus.Status = st;
    irp->IoStatus.Information = 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

static VOID Unload(PDRIVER_OBJECT drv) { UNREFERENCED_PARAMETER(drv); IoDeleteDevice(drv->DeviceObject); }

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg)
{
    UNREFERENCED_PARAMETER(reg);
    UNICODE_STRING name = RTL_CONSTANT_STRING(L"\\Device\\BeRw");
    PDEVICE_OBJECT dev;
    NTSTATUS st = IoCreateDevice(drv, 0, &name, FILE_DEVICE_UNKNOWN, 0, FALSE, &dev);
    if (!NT_SUCCESS(st)) return st;
    drv->MajorFunction[IRP_MJ_CREATE] = drv->MajorFunction[IRP_MJ_CLOSE] = [](PDEVICE_OBJECT d, PIRP i)->NTSTATUS {
        i->IoStatus.Status = STATUS_SUCCESS; i->IoStatus.Information = 0; IoCompleteRequest(i, IO_NO_INCREMENT); return STATUS_SUCCESS; };
    drv->MajorFunction[IRP_MJ_DEVICE_CONTROL] = Dispatch;
    drv->DriverUnload = Unload;
    return STATUS_SUCCESS;
}
```

