# 驱动读写（内核态进程内存读写）— 实现

下面给你一个完整的 WDM 驱动 + 用户态控制程序，实现「驱动层读写任意进程内存」。目标是通用方案，你把目标进程名填进用户态程序即可。

---

## 一、技术路线

```
用户态 Controller.exe
        │  DeviceIoControl(IOCTL_READ / IOCTL_WRITE / IOCTL_MODULEBASE)
        ▼
   \\.\MemDrv  (符号链接)
        │
内核态 MemDrv.sys
        ├─ IoCreateDevice / 符号链接
        ├─ 按 PID 取 EPROCESS → 取 CR3
        ├─ MmCopyVirtualMemory (读写)  ← 关键 API
        └─ 模块基址: PsGetProcessSectionBaseAddress / 遍历 PEB Ldr
```

核心 API 用 `MmCopyVirtualMemory`（走 `KeStackAttachProcess` 附加到目标进程取读，比手搓 CR3 简单且稳）。如果你要 EPT/物理内存读法，后面单独给。

---

## 二、驱动代码 `MemDrv.sys`（WDM）

### `common.h`（共享 IOCTL 定义，用户态也 include 它）

```c
#pragma once
#include <ntifs.h>

#define DEVICE_NAME      L"\\Device\\MemDrv"
#define SYM_LINK_NAME    L"\\DosDevices\\MemDrv"

#define IOCTL_READ_MEM    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_WRITE_MEM   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_MODULE_BASE CTL_CODE(FILE_DEVICE_UNKNOWN, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_GET_PID     CTL_CODE(FILE_DEVICE_UNKNOWN, 0x803, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _MEM_OP {
    ULONG  Pid;          // 目标进程 PID
    ULONG64 Address;     // 目标虚拟地址
    PVOID   Buffer;      // 用户态缓冲区
    SIZE_T  Size;        // 读写大小
    SIZE_T  Returned;    // 实际拷贝字节
} MEM_OP, *PMEM_OP;

typedef struct _MOD_BASE_REQ {
    ULONG  Pid;
    WCHAR  ModuleName[260];   // 空字符串 = 取主模块基址
    ULONG64 Base;
    ULONG64 Size;
} MOD_BASE_REQ, *PMOD_BASE_REQ;

typedef struct _PID_REQ {
    WCHAR ProcessName[260];   // 比如 L"notepad.exe"
    ULONG Pid;
} PID_REQ, *PPID_REQ;
```

### `MemDrv.c`

```c
#include "common.h"

// 通过进程名找 PID（遍历活动进程链表）
static ULONG FindPidByName(_In_ PCWSTR ImageName)
{
    PEPROCESS Process = NULL;
    PLIST_ENTRY Head, Entry;
    ULONG Found = 0;

    Head = PsActiveProcessHead; // 需要在 wdm 里声明 extern
    for (Entry = Head->Flink; Entry != Head; Entry = Entry->Flink) {
        Process = CONTAINING_RECORD(Entry, EPROCESS, ActiveProcessLinks);
        PUNICODE_STRING name = (PUNICODE_STRING)((PUCHAR)Process + 0x5A8); // 偏移随版本变，见下方说明
        if (name && name->Buffer && _wcsicmp(name->Buffer, ImageName) == 0) {
            Found = (ULONG)(ULONG_PTR)PsGetProcessId(Process);
            break;
        }
    }
    return Found;
}

// 走 PEB Ldr 遍历找模块基址
static ULONG64 GetModuleBase(ULONG Pid, PCWSTR ModuleName)
{
    PEPROCESS Process = NULL;
