#define IOCTL_RW CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)

NTSTATUS RwDispatch(PDEVICE_OBJECT Dev, PIRP Irp) {
    PIO_STACK_LOCATION stack = IoGetCurrentIrpStackLocation(Irp);
    NTSTATUS status = STATUS_INVALID_PARAMETER;
    ULONG len = stack->Parameters.DeviceIoControl.OutputBufferLength;

    if (stack->Parameters.DeviceIoControl.IoControlCode == IOCTL_RW && len == sizeof(RW_REQUEST)) {
        PRW_REQUEST req = (PRW_REQUEST)Irp->AssociatedIrp.SystemBuffer;

        PEPROCESS proc = NULL;
        if (NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->Pid, &proc))) {
