bool WorldToScreen(const Matrix4x4& viewProj, const float world[3],
                   float screenW, float screenH, float out[2]) {
    float x = world[0]*viewProj.m[0][0] + world[1]*viewProj.m[1][0] + world[2]*viewProj.m[2][0] + viewProj.m[3][0];
    float y = world[0]*viewProj.m[0][1] + world[1]*viewProj.m[1][1] + world[2]*viewProj.m[2][1] + viewProj.m[3][1];
