    uint32_t blockIdx = (uint32_t)idx >> 16;
    uint32_t offset   = (uint32_t)idx & 0xFFFF;
    uint8_t* entry = g_names->blocks[blockIdx] + offset * 2;
    // entry[0..1] = header；低 10 位为名字长度，后续字节为 ANSI 名字
    int len = *reinterpret_cast<uint16_t*>(entry) & 0x3FF;
    return std::string((char*)(entry + 2), len);
