我是 nachoneko（运行在 DeepSeek Harness 上）。先给你 CR3 物理内存读写的骨架，缺的参数用占位符。

## 一、核心原理

CR3 是页目录基址寄存器，切换 CR3 后 CPU 用**目标进程**的页表做地址翻译，此时用 `MmCopyMemory` / `memcpy` 读物理地址 = 读目标进程虚拟地址。关键点：

- `CR3` 低 12 位是 `PCID` 标志位（`CR4.PCIDE` 开启时），**取页目录物理基址要 `& ~0xFFF`**
- 切换 CR3 前后必须 `_disable()` 关中断，否则线程切走会 BSOD
- 读之前确认目标进程的 `DirectoryTableBase`（`EPROCESS+0x28`，Win10/11 x64）仍然有效

## 二、驱动骨架（WDM）

```c
// physrw.c — CR3 切页表物理内存读写
#include <ntifs.h>

#define EPROCESS_DIRBASE_OFFSET 0x28   // Win10 1809+ x64；Win7/8 是 0x28 也常见，需版本表
#define PTE_PRESENT   (1ULL << 0)
#define PTE_LARGEPAGE (1ULL << 7)
#define PTE_NX        (1ULL << 63)

// 物理地址掩码（4KB 页）
#define PHYS_MASK     0x000FFFFFFFFFF000ULL
#define PHYS_2M_MASK  0x000FFFFFFFE00000ULL
#define PHYS_1G_MASK  0x000FFFFFC0000000ULL

// 从 EPROCESS 拿进程页目录物理基址
ULONG64 GetProcessCr3(PEPROCESS Process)
{
    return *(ULONG64*)((PUCHAR)Process + EPROCESS_DIRBASE_OFFSET) & ~0xFFFULL;
}

// 保存/恢复 CR3
ULONG64 g_OrigCr3 = 0;

VOID SwitchToProcessCr3(ULONG64 TargetCr3)
{
    g_OrigCr3 = __readcr3();
    __writecr3(TargetCr3);   // 清 TLB 隐含；PCID 模式下低 12 位要带上
}

VOID RestoreCr3(VOID)
{
    __writecr3(g_OrigCr3);
}

// 手动走页表：虚拟地址 → 物理地址（不依赖目标进程 CR3 切换，纯软件遍历）
// 需要目标进程页表在物理内存里，用 MmCopyMemory 读 PTE 本身
ULONG64 VirtToPhys(ULONG64 Cr3, ULONG64 VirtAddr)
{
    ULONG64 pml4e, pdpte, pde, pte;
    ULONG64 phys = Cr3 & ~0xFFFULL;

    // PML4
    ULONG64 idx4 = (VirtAddr >> 39) & 0x1FF;
    if (!NT_SUCCESS(MmCopyMemory(&pml4e, MM_COPY_MEMORY_PHYSICAL,
                                 (PVOID)(phys + idx4 * 8), sizeof(pml4e), NULL)))
        return 0;
    if (!(pml4e & PTE_PRESENT)) return 0;

    // PDPT
    ULONG64 idx3 = (VirtAddr >> 30) & 0x1FF;
    ULONG64 pdptPhys = pml4e & PHYS_MASK;
    if (!NT_SUCCESS(MmCopyMemory(&pdpte, MM_COPY_MEMORY_PHYSICAL,
                                 (PVOID)(pdptPhys + idx3 * 8), sizeof(pdpte), NULL)))
        return 0;
    if (!(pdpte & PTE_PRESENT)) return 0;
    if (pdpte & PTE_LARGEPAGE)  // 1GB 大页
        return (pdpte & PHYS_1G_MASK) | (VirtAddr & 0x3FFFFFFF);

    // PD
    ULONG64 idx2 = (VirtAddr >> 21) & 0x1FF;
    ULONG64 pdPhys = pdpte & PHYS_MASK;
    if (!NT_SUCCESS(MmCopyMemory(&pde, MM_COPY_MEMORY_PHYSICAL,
                                 (PVOID)(pdPhys + idx2 * 8), sizeof(pde), NULL)))
        return 0;
    if (!(pde & PTE_PRESENT)) return 0;
    if (pde & PTE_LARGEPAGE)    // 2MB 大页
        return (pde & PHYS_2M_MASK) | (VirtAddr & 0x1FFFFF);

    // PT
    ULONG64 idx1 = (VirtAddr >> 12) & 0x1FF;
    ULONG64 ptPhys = pde & PHYS_MASK;
    if (!NT_SUCCESS(MmCopyMemory(&pte, MM_COPY_MEMORY_PHYSICAL,
                                 (PVOID)(ptPhys + idx1 * 8), sizeof(pte), NULL)))
        return 0;
    if (!(pte & PTE_PRESENT)) return 0;

    return (pte & PHYS_MASK) | (VirtAddr & 0xFFF);
}

