## 3. CR3 获取（遍历 `ActiveProcessLinks`）

```c
ULONG64 GetProcessCr3(ULONG Pid)
{
    PEPROCESS SysProc = PsGetCurrentProcess();
    PEPROCESS Proc    = NULL;
    PLIST_ENTRY Head, Entry;

    // ActiveProcessLinks 头节点在 System 进程里
    Head = (PLIST_ENTRY)((PUCHAR)SysProc + EPROCESS_FLINK_OFF);
    Entry = Head->Flink;

    while (Entry != Head) {
        Proc = (PEPROCESS)((PUCHAR)Entry - EPROCESS_FLINK_OFF);
        if (*(ULONG*)((PUCHAR)Proc + EPROCESS_PID_OFF) == Pid) {
            return *(ULONG64*)((PUCHAR)Proc + KPROCESS_DTB_OFF);
        }
        Entry = Entry->Flink;
    }
    return 0;
}
```

