kmbox 走串口就是发固定长度的字节帧，关键在于**波特率、帧头、数据编码顺序**。先按 kmbox Net / kmbox B+ 两条常见线给出可直接跑的代码，未知的 VID/PID 和端口用占位符。

## 一、协议帧结构

kmbox 的串口协议本质是「固定长度指令帧 + 小端多字节数据」。以 kmbox B+ 系列（USB 转串口，`CH340` / `CP210x` 芯片，115200 8N1）为例，手柄数据帧格式：

```
[0xA5][按键字节][X低][X高][Y低][Y高][滚轮][CRC8]
```

- 输入为**有符号 16 位**，鼠标位移范围约 `-32767 ~ 32767`；
- 位移是**相对增量**，不是绝对坐标——每次发的是这一帧要移动多少，硬件自己上报；
- CRC8 多项式 `0x07`，初值 `0x00`，覆盖从帧头到滚轮的所有字节。

## 二、串口打开与帧发送（Windows C++）

```cpp
#include <windows.h>
#include <stdint.h>

// 打开串口：COMx 换成你设备管理器里看到的端口
HANDLE OpenKmBox(const wchar_t* port, int baud) {
    HANDLE h = CreateFileW(port, GENERIC_READ | GENERIC_WRITE, 0, nullptr,
                           OPEN_EXISTING, 0, nullptr);
    if (h == INVALID_HANDLE_VALUE) return nullptr;

    DCB dcb = { sizeof(DCB) };
    GetCommState(h, &dcb);
    dcb.BaudRate = baud;
    dcb.ByteSize = 8;
    dcb.Parity   = NOPARITY;
    dcb.StopBits = ONESTOPBIT;
    dcb.fBinary  = TRUE;
    dcb.fParity  = FALSE;
    SetCommState(h, &dcb);

    COMMTIMEOUTS to = {};
    to.ReadIntervalTimeout        = MAXDWORD;
    to.ReadTotalTimeoutMultiplier = 0;
    to.ReadTotalTimeoutConstant   = 0;
    to.WriteTotalTimeoutConstant  = 50;
    SetCommTimeouts(h, &to);
    return h;
}

// CRC8 多项式 0x07
static uint8_t Crc8(const uint8_t* p, size_t n) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < n; ++i) {
        crc ^= p[i];
        for (int b = 0; b < 8; ++b)
            crc = (crc & 0x80) ? (uint8_t)((crc << 1) ^ 0x07) : (uint8_t)(crc << 1);
    }
    return crc;
}

// 发送一帧相对位移
bool KmBoxMove(HANDLE h, int16_t dx, int16_t dy, int8_t wheel = 0) {
    uint8_t frame[8];
    frame[0] = 0xA5;
    frame[1] = 0x00;                    // 按键位，左键=0x01 右键=0x02
    frame[2] = (uint8_t)(dx & 0xFF);    // X 低字节
    frame[3] = (uint8_t)((dx >> 8) & 0xFF);
    frame[4] = (uint8_t)(dy & 0xFF);
    frame[5] = (uint8_t)((dy >> 8) & 0xFF);
    frame[6] = (uint8_t)wheel;
    frame[7] = Crc8(frame, 7);

    DWORD written = 0;
    return WriteFile(h, frame, sizeof(frame), &written, nullptr) && written == 8;
}
```

