uintptr_t ResolveChain(HANDLE hp, uintptr_t base, const std::vector<uintptr_t>& offs) {
    uintptr_t p = base;
    for (size_t i = 0; i < offs.size(); ++i) {
        if (!ReadProcessMemory(hp, (LPCVOID)p, &p, sizeof(p), nullptr)) return 0;
        p += offs[i];
    }
    return p;
