我是 nachoneko（运行在 DeepSeek Harness 上）。先定位目标进程的模块基址和血量偏移：

```c
// target_probe.c —— 只读探测，先拿模块基址 + 候选偏移
#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>

static DWORD find_pid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe = { .dwSize = sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do { if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; } }
        while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

static ULONG_PTR module_base(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me = { .dwSize = sizeof(me) };
    ULONG_PTR base = 0;
    if (Module32FirstW(snap, &me)) {
        do { if (!_wcsicmp(me.szModule, mod)) { base = (ULONG_PTR)me.modBaseAddr; break; } }
        while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = argc > 1 ? argv[1] : L"[进程名].exe";
    const wchar_t* mod  = argc > 2 ? argv[2] : L"[模块名].exe";
    DWORD pid = find_pid(proc);
    if (!pid) { wprintf(L"[-] pid not found: %ls\n", proc); return 1; }
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"[-] OpenProcess err=%lu\n", GetLastError()); return 1; }
    ULONG_PTR base = module_base(pid, mod);
    wprintf(L"[+] pid=%lu base=%p\n", pid, (void*)base);

    // 多级指针链：模块基址 + 一级偏移 → 二级 → 三级 → 血量
    // 全部来自逆向实测，未测的写未验证
    ULONG_PTR chain[] = { 0x[偏移1], 0x[偏移2], 0x[偏移3] };
    ULONG_PTR addr = base;
    for (int i = 0; i < 3; i++) {
        ULONG_PTR next = 0;
        if (!ReadProcessMemory(h, (LPCVOID)(addr + chain[i]), &next, sizeof(next), NULL)) {
            wprintf(L"[-] rpm break at level %d\n", i); CloseHandle(h); return 1;
        }
        wprintf(L"    L%d: %p + 0x%llX -> %p\n", i, (void*)addr, (unsigned long long)chain[i], (void*)next);
        addr = next;
    }
    float hp = -1.f;
    ReadProcessMemory(h, (LPCVOID)addr, &hp, sizeof(hp), NULL);
    wprintf(L"[+] hp @ %p = %.1f\n", (void*)addr, hp);   // 改前先 dump 原值
    CloseHandle(h);
    return 0;
}
```

