```cpp
// target_read.cpp — 用户态读写最小骨架，用于后续偏移验证
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>

DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (Process32FirstW(snap, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(snap); return pe.th32ProcessID; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return 0;
}

uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    if (Module32FirstW(snap, &me)) do {
        if (!_wcsicmp(me.szModule, mod)) { CloseHandle(snap); return (uintptr_t)me.modBaseAddr; }
    } while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return 0;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = argc > 1 ? argv[1] : L"[进程名].exe";
    const wchar_t* mod  = argc > 2 ? argv[2] : L"[模块名].exe";
    DWORD pid = GetPid(proc);
    if (!pid) { wprintf(L"pid not found\n"); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess failed: %lu\n", GetLastError()); return 1; }

    uintptr_t base = GetModuleBase(pid, mod);
    wprintf(L"pid=%lu base=0x%llX\n", pid, (unsigned long long)base);

    // 多级指针链解析：[模块基址] + 偏移链，最后一级读数值
    uintptr_t addr = base + [基址偏移];
    uintptr_t chain[] = { [偏移1], [偏移2], [偏移3] };   // 逐跳 deref
    for (uintptr_t off : chain) {
        uintptr_t next = 0;
        if (!ReadProcessMemory(h, (LPCVOID)addr, &next, sizeof(next), nullptr)) {
            wprintf(L"chain break @0x%llX\n", (unsigned long long)addr); CloseHandle(h); return 1;
        }
        addr = next + off;
    }
    float value = 0.f;
    ReadProcessMemory(h, (LPCVOID)addr, &value, sizeof(value), nullptr);
    wprintf(L"value = %f  @0x%llX\n", value, (unsigned long long)addr);

    CloseHandle(h);
    return 0;
}
```

编译：`cl /EHsc /O2 target_read.cpp`

