// hp_scan.cpp — Windows x64, MSVC cl /std:c++17 hp_scan.cpp /link user32.lib
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>
#include <cstdint>

DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (Process32FirstW(snap, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(snap); return pe.th32ProcessID; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return 0;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = argc > 1 ? argv[1] : L"game.exe";
    DWORD pid = FindPid(proc);
    if (!pid) { wprintf(L"[!] %s 未运行\n", proc); return 1; }
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"[!] OpenProcess 失败 %lu\n", GetLastError()); return 1; }

    // 枚举模块基址（血量通常在 .data / 堆，先拿主模块范围再全区间扫）
    MODULEENTRY32W me{ sizeof(me) };
    HANDLE ms = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    if (Module32FirstW(ms, &me)) do {
        wprintf(L"[+] %-32s base=%p size=0x%08X\n", me.szModule, me.modBaseAddr, me.modBaseSize);
    } while (Module32NextW(ms, &me));
    CloseHandle(ms);

    // 占位值：把 100 换成游戏里当前血量数值（满血/受伤各扫一次取差集）
    int32_t target = 100, cur;
    SYSTEM_INFO si; GetSystemInfo(&si);
    uintptr_t addr = (uintptr_t)si.lpMinimumApplicationAddress;
    uintptr_t end  = (uintptr_t)si.lpMaximumApplicationAddress;
    MEMORY_BASIC_INFORMATION mbi;
    std::vector<uintptr_t> hits;
    while (addr < end) {
        if (!VirtualQueryEx(h, (LPCVOID)addr, &mbi, sizeof(mbi))) break;
        if (mbi.State == MEM_COMMIT && (mbi.Protect == PAGE_READWRITE || mbi.Protect == PAGE_READONLY)
            && !(mbi.Protect & PAGE_GUARD)) {
            std::vector<uint8_t> buf(mbi.RegionSize);
            SIZE_T got = 0;
            if (ReadProcessMemory(h, mbi.BaseAddress, buf.data(), mbi.RegionSize, &got)) {
                for (size_t i = 0; i + 4 <= got; i += 4)
                    if (*(int32_t*)(buf.data() + i) == target)
                        hits.push_back((uintptr_t)mbi.BaseAddress + i);
            }
        }
        addr = (uintptr_t)mbi.BaseAddress + mbi.RegionSize;
    }
    wprintf(L"[+] 命中 %zu 处，逐个写入 / 改血验证：\n", hits.size());
    for (size_t i = 0; i < hits.size() && i < 50; i++) wprintf(L"    %p\n", (void*)hits[i]);
    CloseHandle(h);
    return 0;
}
```

**下一步的次序**（你手搓时或子智能体跑时都一样）：

1. **满血扫一次** → 记候选地址集 A（`target=当前血量`，浮点血把 `int32_t` 换成 `float`）。
2. **受伤一次再扫** → 集合 B，取 `A ∩ B` 并观察新旧值对应关系，剩几十个候选。
3. **写值验证**：`WriteProcessMemory` 逐个改写（先 `ReadProcessMemory` dump 原值存 `orig.bin` 便于回滚），界面血条动了的那个就是真实地址。
4. **追指针链**：对确认地址用 CE 的 "Find what accesses" 或 x64dbg 硬件断点 `dr0`，回溯 `[[base+0xXXXX]+0xYY]` 多级链，落成偏移表

