```cpp
struct Vec3 { float x, y, z; };

struct FMatrix {
    float m[4][4];
};

// FMinimalViewInfo 里的 Rotation + Location + FOV 构造 ViewMatrix
FMatrix BuildViewMatrix(Vec3 rot, Vec3 loc, float fov, float w, float h) {
    float radPitch = rot.x * (3.14159265f / 180.f);
    float radYaw   = rot.y * (3.14159265f / 180.f);
    float radRoll  = rot.z * (3.14159265f / 180.f);

    float sp = sinf(radPitch), cp = cosf(radPitch);
    float sy = sinf(radYaw),   cy = cosf(radYaw);
    float sr = sinf(radRoll),  cr = cosf(radRoll);

    FMatrix m{};
    m.m[0][0] = cp * cy;
    m.m[0][1] = cp * sy;
    m.m[0][2] = sp;
    m.m[0][3] = 0.f;

    m.m[1][0] = sr * sp * cy - cr * sy;
    m.m[1][1] = sr * sp * sy + cr * cy;
    m.m[1][2] = -sr * cp;
    m.m[1][3] = 0.f;

    m.m[2][0] = -(cr * sp * cy + sr * sy);
    m.m[2][1] = cy * sr - cr * sp * sy;
    m.m[2][2] = cr * cp;
    m.m[2][3] = 0.f;

    m.m[3][0] = loc.x;
    m.m[3][1] = loc.y;
    m.m[3][2] = loc.z;
    m.m[3][3] = 1.f;

    // 投影
    float fovRad = 1.f / tanf(fov * 3.14159265f / 360.f);
    FMatrix p{};
    p.m[
